.cbesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2433;
    background: linear-gradient(168deg, #f5f3ee 0%, #eef0f4 60%, #e7eaf1 100%);
    border-radius: 18px;
}

.cbesim-container * {
    box-sizing: border-box;
}

.cbesim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #14243f 0%, #1f3a63 55%, #2a4f87 100%);
    color: #f4f6fb;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(20, 36, 63, 0.32);
    border-bottom: 3px solid #c9a44c;
}

.cbesim-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.cbesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e9c878;
    background: rgba(201, 164, 76, 0.14);
    border: 1px solid rgba(201, 164, 76, 0.42);
    padding: 5px 14px;
    border-radius: 999px;
}

.cbesim-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdd7e8;
}

.cbesim-parties {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.cbesim-party {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(20, 36, 63, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.cbesim-party-centre { border-left: 5px solid #c9a44c; }
.cbesim-party-client { border-left: 5px solid #2a4f87; }

.cbesim-party-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #14243f;
}

.cbesim-party-centre .cbesim-party-name { color: #a87f1f; }
.cbesim-party-client .cbesim-party-name { color: #2a4f87; }

.cbesim-party-meta {
    font-size: 0.82rem;
    color: #5a6577;
    line-height: 1.4;
}

.cbesim-party-plus {
    align-self: center;
    font-size: 1.7rem;
    font-weight: 800;
    color: #1f3a63;
}

.cbesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #45506a;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.cbesim-period-counter #currentDay,
.cbesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #a87f1f;
}

.cbesim-round-name {
    background: rgba(42, 79, 135, 0.12);
    color: #2a4f87;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cbesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8612c;
    background: rgba(196, 110, 46, 0.13);
    border: 1px solid rgba(196, 110, 46, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.cbesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cbesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(20, 36, 63, 0.08);
    border-top: 4px solid #2a4f87;
}

.cbesim-card-margin { border-top-color: #c9a44c; }
.cbesim-card-capacity { border-top-color: #2a4f87; }
.cbesim-card-nps { border-top-color: #2f8f6f; }
.cbesim-card-repeat { border-top-color: #7d5fc0; }

.cbesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7689;
}

.cbesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14243f;
    font-variant-numeric: tabular-nums;
}

.cbesim-card-margin .cbesim-value { color: #a87f1f; font-size: 2.9rem; }
.cbesim-card-capacity .cbesim-value { color: #2a4f87; }
.cbesim-card-nps .cbesim-value { color: #2f8f6f; }
.cbesim-card-repeat .cbesim-value { color: #7d5fc0; }

.cbesim-sublabel {
    font-size: 0.76rem;
    color: #76819a;
    line-height: 1.35;
}

/* Margin tells the story: red below the 30% floor, amber near it, green clear of it. */
.cbesim-card-margin.cbesim-margin-breach { border-top-color: #d64545; }
.cbesim-card-margin.cbesim-margin-breach .cbesim-value { color: #d64545; }
.cbesim-card-margin.cbesim-margin-warn { border-top-color: #c46e2e; }
.cbesim-card-margin.cbesim-margin-warn .cbesim-value { color: #c46e2e; }
.cbesim-card-margin.cbesim-margin-good { border-top-color: #2f8f6f; }
.cbesim-card-margin.cbesim-margin-good .cbesim-value { color: #2f8f6f; }

/* Capacity over the available pool turns red. */
.cbesim-card-capacity.cbesim-capacity-over { border-top-color: #d64545; }
.cbesim-card-capacity.cbesim-capacity-over .cbesim-value { color: #d64545; }
.cbesim-card-capacity.cbesim-capacity-tight { border-top-color: #c46e2e; }
.cbesim-card-capacity.cbesim-capacity-tight .cbesim-value { color: #c46e2e; }

.cbesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dfe4ec;
    color: #45506a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cbesim-budget-bar #priceDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #2a4f87;
    font-weight: 800;
}

.cbesim-budget-bar.cbesim-budget-over #priceDisplay { color: #d64545; }
.cbesim-budget-bar.cbesim-budget-under #priceDisplay { color: #2f8f6f; }

.cbesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a44c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 36, 63, 0.07);
}

.cbesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cbesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14243f;
    margin-bottom: 6px;
}

.cbesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4458;
}

.cbesim-briefing-text strong { color: #1f3a63; }
.cbesim-briefing-text em { color: #a8612c; font-style: italic; }

.cbesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 36, 63, 0.07);
}

.cbesim-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14243f;
    border-bottom: 2px solid #ece7da;
    padding-bottom: 8px;
}

.cbesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3548;
    margin: 14px 0 6px;
}

.cbesim-container select,
.cbesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c7cfdb;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1d2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cbesim-container select:focus,
.cbesim-container input[type="number"]:focus {
    outline: none;
    border-color: #c9a44c;
    box-shadow: 0 0 0 3px rgba(201, 164, 76, 0.18);
}

.cbesim-container select option {
    background-color: #ffffff;
    color: #1d2433;
}

.cbesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c9a44c;
}

.cbesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #45506a;
    margin-top: 4px;
}

.cbesim-range-readout span:nth-child(2) {
    color: #a87f1f;
    font-weight: 800;
}

.cbesim-hint {
    font-size: 0.8rem;
    color: #76819a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.cbesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cbesim-container .btn-primary {
    background: linear-gradient(135deg, #1f3a63 0%, #2a4f87 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(31, 58, 99, 0.32);
}

.cbesim-container .btn-primary:hover {
    filter: brightness(1.10);
}

.cbesim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c7cfdb;
    color: #5a6577;
    background: transparent;
}

.cbesim-coach {
    background: linear-gradient(160deg, #14243f 0%, #1b3052 100%);
    color: #e4ebf6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(20, 36, 63, 0.26);
    border-left: 4px solid #c9a44c;
}

.cbesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e9c878;
    margin-bottom: 8px;
}

.cbesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cbesim-coach-body strong { color: #e9c878; }
.cbesim-coach-body em { color: #9fc3ff; font-style: italic; }

.cbesim-history,
.cbesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 36, 63, 0.07);
}

.cbesim-history h3,
.cbesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14243f;
}

.cbesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4458;
}

.cbesim-container table#usfHistoryTable th {
    background: #f1eee4;
    color: #a87f1f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e4ddca;
}

.cbesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef0f3;
    color: #3a4458;
}

.cbesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8f6f0;
}

.cbesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cbesim-container {
        padding: 14px;
    }
    .cbesim-header h1 {
        font-size: 1.7rem;
    }
    .cbesim-parties {
        flex-direction: column;
    }
    .cbesim-party-plus {
        transform: rotate(90deg);
    }
    .cbesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cbesim-value {
        font-size: 2rem;
    }
    .cbesim-card-margin .cbesim-value {
        font-size: 2.2rem;
    }
    .cbesim-clock {
        margin-left: 0;
    }
    .cbesim-period-counter {
        font-size: 0.88rem;
    }
    .cbesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cbesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.cp-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.cp-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.cp-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.cp-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.cp-cm-score strong { color: #4f9bd9; }
.cp-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.cp-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.cp-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.cp-cm-target.cp-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.cp-cm-target.cp-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.cp-cm-tick { font-weight: 700; }
.cp-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.cp-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.cp-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.cp-cm-metric strong { font-size: 16px; color: #eceff6; }
.cp-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.cp-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .cp-cm-metric { min-width: 70px; } .cp-cm-verdict { font-size: 19px; } }

