(function() {
    'use strict';

    class CustomProgramAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Custom Program`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (CBE-Adriatic / NovaBank) ----
            this.MARGIN_FLOOR = 30;       // board-mandated minimum contribution margin (%)
            this.START_MARGIN = 19;       // wished-for bundle starts at 19%
            this.STAR_CAP = 40;           // two star professors: 18 + 22 days left
            this.WISH_DAYS = 34;          // wish list demands 34 star-faculty days
            this.BUDGET = 540;            // NovaBank indicated budget (€000)
            this.REPEAT_PROGRAM = 180;    // repeat sustainability program at stake (€000)
            this.START_REPEAT = 68;       // repeat-business rate at outset (%)

            // Concept truths (the modelled solution-design path).
            this.TRUE_NEED = `objective`;
            this.TRUE_FORMAT = `blended`;
            this.TRUE_FACULTY = `20`;
            this.TRUE_ADDONS = `targeted`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: this.START_MARGIN,    // contribution margin (%)
                    starDays: 0,                  // star-faculty days committed
                    nps: 0,                       // expected client NPS (−100..+100)
                    repeat: this.START_REPEAT,    // repeat-business rate (%)
                    price: this.BUDGET,           // proposed price (€000)
                    npsSet: false,                // NPS only meaningful once a design exists
                    ordertaking: false,           // committed the order-taking error
                    overMargin: false,            // over-corrected and stripped the premium
                    capacityBlind: false,         // over-committed star days
                    freeConcession: false,        // conceded with nothing in return
                    soldActivity: false,          // sold activity over impact
                    droppedRepeat: false,         // dropped the repeat client
                    securedValue: 0,              // future business secured in trades (€000)
                    marginHistory: [this.START_MARGIN],
                    starHistory: [0],
                    npsHistory: [0],
                    repeatHistory: [this.START_REPEAT],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    need: `wishlist`,
                    bind: `price`,
                    posture: `ordertake`,
                    diligence: 30,
                    format: `residential`,
                    faculty: `34`,
                    addons: `all`,
                    price: 540,
                    procurement: `cave`,
                    substitute: `never`,
                    repeat: `drop`,
                    concession: 0,
                    pitch: `activity`,
                    measure: `happy`,
                    relationship: `oneoff`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const nd = document.getElementById(`needInput`);
                const bi = document.getElementById(`bindInput`);
                const po = document.getElementById(`postureInput`);
                const di = document.getElementById(`diligenceInput`);
                if (nd) decisions.need = nd.value;
                if (bi) decisions.bind = bi.value;
                if (po) decisions.posture = po.value;
                if (di) decisions.diligence = parseInt(di.value, 10);
                if (!Number.isFinite(decisions.diligence) || decisions.diligence < 0 || decisions.diligence > 100) {
                    warn(`warn_diligence_range`); return false;
                }
            } else if (round === 2) {
                const fo = document.getElementById(`formatInput`);
                const fa = document.getElementById(`facultyInput`);
                const ad = document.getElementById(`addonsInput`);
                const pr = document.getElementById(`priceInput`);
                if (fo) decisions.format = fo.value;
                if (fa) decisions.faculty = fa.value;
                if (ad) decisions.addons = ad.value;
                if (pr) decisions.price = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.price) || decisions.price < 300 || decisions.price > 700) {
                    warn(`warn_price_range`); return false;
                }
            } else if (round === 3) {
                const pc = document.getElementById(`procurementInput`);
                const su = document.getElementById(`substituteInput`);
                const re = document.getElementById(`repeatInput`);
                const co = document.getElementById(`concessionInput`);
                if (pc) decisions.procurement = pc.value;
                if (su) decisions.substitute = su.value;
                if (re) decisions.repeat = re.value;
                if (co) decisions.concession = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.concession) || decisions.concession < 0) {
                    warn(`warn_concession_value`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const me = document.getElementById(`measureInput`);
                const rl = document.getElementById(`relationshipInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (me) decisions.measure = me.value;
                if (rl) decisions.relationship = rl.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let marginDelta = 0, npsDelta = 0, repeatDelta = 0, starDaysSet = null;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: solution design vs order-taking (Common Error 1).
                switch (d.need) {
                    case `objective`: marginDelta += 1; npsDelta += 4; coachKey = `coach_r1_objective`; break;
                    case `wishlist`: marginDelta -= 1; ds.ordertaking = true; coachKey = `coach_r1_wishlist`; break;
                    case `prestige`: marginDelta -= 2; npsDelta += 2; coachKey = `coach_r1_prestige`; break;
                }

                switch (d.bind) {
                    case `margincap`: marginDelta += 2; coachKey = `coach_r1_margincap`; break;
                    case `price`: marginDelta -= 1; coachKey = `coach_r1_price`; break;
                    case `winprob`: marginDelta -= 2; npsDelta += 1; coachKey = `coach_r1_winprob`; break;
                }

                switch (d.posture) {
                    case `consult`: npsDelta += 3; marginDelta += 1; if (d.need === `objective`) coachKey = `coach_r1_sharp`; break;
                    case `ordertake`: npsDelta += 2; marginDelta -= 2; ds.ordertaking = true; coachKey = `coach_r1_ordertake`; break;
                    case `lowball`: marginDelta += 1; npsDelta -= 4; ds.overMargin = true; coachKey = `coach_r1_lowball`; break;
                }

                // Diligence = the discovery that makes a good design possible.
                if (d.diligence >= 50) { marginDelta += 1; npsDelta += 2; }
                else if (d.diligence <= 15) { npsDelta -= 2; marginDelta -= 1; }

                summaryKey = (d.need === `objective` && d.bind === `margincap` && d.posture === `consult`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- THE CORE DESIGN ROUND ----
                // Margin and NPS are reset to a level set by the design, not nudged.
                ds.price = d.price;

                // Star-faculty days are SET by the faculty-mix choice.
                starDaysSet = parseInt(d.faculty, 10);

                // Base margin and NPS by format.
                let baseMargin, baseNps;
                switch (d.format) {
                    case `residential`: baseMargin = 37; baseNps = 56; break;   // premium experience, costly
                    case `online`:      baseMargin = 40; baseNps = 24; ds.overMargin = true; break; // cheap, thin
                    case `blended`:     baseMargin = 34; baseNps = 50; break;   // the design answer (centre's blended norm)
                    default:            baseMargin = 32; baseNps = 42; break;
                }

                // Faculty mix moves margin (star days are expensive) and NPS (senior faculty is the value).
                switch (d.faculty) {
                    case `34`: baseMargin -= 10; baseNps += 14; ds.capacityBlind = true; break; // burns margin and capacity
                    case `6`:  baseMargin += 6;  baseNps -= 22; ds.overMargin = true; break;     // strips the premium
                    case `20`: baseMargin += 1;  baseNps += 7;  break;                            // leverage stars
                }

                // Add-on depth.
                switch (d.addons) {
                    case `all`:      baseMargin -= 8;  baseNps += 12; break;  // the bundle that lands ~19% with residential + 34 days
                    case `none`:     baseMargin += 6;  baseNps -= 16; break;  // ignores what they asked for
                    case `targeted`: baseMargin += 1;  baseNps += 6;  break;  // impact-tied, margin-aware
                }

                // Price vs budget: pricing above budget lifts margin but threatens the win (NPS proxy for
                // win probability here); pricing below erodes margin.
                const priceGap = d.price - this.BUDGET;          // €000
                baseMargin += priceGap / 12;                      // ~+8pts at €636k, ~−8pts at €444k
                if (priceGap > 60) { baseNps -= 14; coachKey = `coach_r2_overprice`; }
                else if (priceGap < -60) { baseNps += 6; }        // a discount reads well short-term

                // Carry a little of Round 1's diagnosis into the design quality.
                if (d.need === `objective`) baseMargin += 1;

                ds.margin = baseMargin;
                ds.nps = baseNps;
                ds.npsSet = true;
                marginDelta = 0; npsDelta = 0;   // margin/nps were SET, not nudged, this round

                const onBudget = Math.abs(priceGap) <= 60;
                if (d.format === `blended` && d.faculty === `20` && d.addons === `targeted` && onBudget) {
                    coachKey = `coach_r2_solution`;
                } else if (d.format === `residential` && d.faculty === `34` && d.addons === `all`) {
                    coachKey = `coach_r2_ordertaking`;
                } else if (d.format === `online` && d.faculty === `6`) {
                    coachKey = `coach_r2_stripped`;
                } else if (starDaysSet > this.STAR_CAP) {
                    coachKey = `coach_r2_capacity`;
                } else if (coachKey === `coach_default`) {
                    coachKey = `coach_r2_mixed`;
                }

                summaryKey = (d.format === `blended` && d.faculty === `20` && d.addons === `targeted`) ? `sum_r2_good` :
                             (d.format === `residential` && d.faculty === `34` && d.addons === `all`) ? `sum_r2_ordertaking` :
                             (d.format === `online` || d.faculty === `6`) ? `sum_r2_stripped` : `sum_r2_mixed`;
            } else if (round === 3) {
                // Resolve the squeeze: procurement, substitution, the repeat client (Common Errors 3, 4, 5).
                ds.securedValue = d.concession;

                // (a) Procurement push: "more star time, same budget".
                switch (d.procurement) {
                    case `trade`:
                        // Concession only pays off if real value is secured.
                        if (d.concession >= 120) {
                            marginDelta += 1; npsDelta += 8; repeatDelta += 6; coachKey = `coach_r3_trade`;
                        } else {
                            // Said "trade" but secured little — effectively a soft giveaway.
                            marginDelta -= 4; npsDelta += 5; ds.freeConcession = true; coachKey = `coach_r3_thintrade`;
                        }
                        break;
                    case `cave`:
                        marginDelta -= 7; npsDelta += 9; starDaysSet = (ds.starDays || 0) + 8; ds.freeConcession = true; coachKey = `coach_r3_cave`;
                        break;
                    case `refuse`:
                        marginDelta += 2; npsDelta -= 8; coachKey = `coach_r3_refuse`;
                        break;
                }

                // (b) Substitution where the star is not essential.
                switch (d.substitute) {
                    case `selective`: marginDelta += 5; npsDelta += 2; if (starDaysSet === null) starDaysSet = Math.max(6, (ds.starDays || 0) - 6); break;
                    case `never`: marginDelta -= 4; npsDelta += 3; ds.capacityBlind = true; coachKey = (coachKey === `coach_default`) ? `coach_r3_neversub` : coachKey; break;
                    case `everywhere`: marginDelta += 6; npsDelta -= 12; ds.overMargin = true; if (starDaysSet === null) starDaysSet = 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_oversub` : coachKey; break;
                }

                // (c) The repeat sustainability client (Common Error 5 — client lifetime value).
                switch (d.repeat) {
                    case `resequence`: repeatDelta += 14; npsDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_resequence` : coachKey; break;
                    case `drop`: repeatDelta -= 22; ds.droppedRepeat = true; coachKey = `coach_r3_drop`; break;
                    case `overcommit`: repeatDelta -= 10; npsDelta -= 6; ds.capacityBlind = true; coachKey = `coach_r3_overcommit`; break;
                }

                summaryKey = (d.procurement === `trade` && d.concession >= 120 && d.substitute === `selective` && d.repeat === `resequence`) ? `sum_r3_good` :
                             (d.procurement === `cave`) ? `sum_r3_free` :
                             (d.repeat === `drop`) ? `sum_r3_dropped` : `sum_r3_mixed`;
            } else if (round === 4) {
                // Pitch the engagement: impact over activity (Common Error 5/6).
                switch (d.pitch) {
                    case `impact`: npsDelta += 10; repeatDelta += 6; marginDelta += 1; coachKey = `coach_r4_impact`; break;
                    case `activity`: npsDelta -= 8; ds.soldActivity = true; coachKey = `coach_r4_activity`; break;
                    case `price`: npsDelta -= 4; marginDelta -= 2; coachKey = `coach_r4_price`; break;
                }

                switch (d.measure) {
                    case `behaviour`: npsDelta += 6; repeatDelta += 8; coachKey = (coachKey === `coach_default`) ? `coach_r4_behaviour` : coachKey; break;
                    case `happy`: npsDelta -= 3; ds.soldActivity = true; break;
                    case `completion`: npsDelta -= 1; break;
                }

                switch (d.relationship) {
                    case `partnership`: repeatDelta += 12; npsDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_partnership` : coachKey; break;
                    case `oneoff`: repeatDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_oneoff` : coachKey; break;
                    case `discount`: marginDelta -= 5; repeatDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_discount` : coachKey; break;
                }

                if (d.conviction >= 60) { npsDelta += 3; repeatDelta += 2; }
                else if (d.conviction <= 25) { npsDelta -= 2; }

                summaryKey = (d.pitch === `impact` && d.measure === `behaviour` && d.relationship === `partnership`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply star-faculty days if this round set them. ----
            if (starDaysSet !== null) {
                ds.starDays = Math.max(0, Math.round(starDaysSet));
            }

            // ---- Capacity penalty: committing more than the 40-day pool means the
            // calendar collides — margin and NPS both suffer when promises can't be kept. ----
            if (ds.starDays > this.STAR_CAP) {
                const over = ds.starDays - this.STAR_CAP;
                marginDelta -= over * 0.4;   // overtime / premium adjuncts to cover the gap
                npsDelta -= over * 0.8;       // a promise that breaks in month four
            }

            // ---- Apply deltas (clamped). ----
            ds.margin = Math.max(0, Math.min(60, Math.round((ds.margin + marginDelta) * 10) / 10));
            if (ds.npsSet) {
                ds.nps = Math.max(-100, Math.min(100, Math.round(ds.nps + npsDelta)));
            }
            ds.repeat = Math.max(0, Math.min(100, Math.round((ds.repeat + repeatDelta) * 10) / 10));

            ds.marginHistory.push(ds.margin);
            ds.starHistory.push(ds.starDays);
            ds.npsHistory.push(ds.npsSet ? ds.nps : 0);
            ds.repeatHistory.push(ds.repeat);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                starDays: ds.starDays,
                nps: ds.npsSet ? ds.nps : null,
                repeat: ds.repeat,
                repeatDelta: Math.round(repeatDelta * 10) / 10,
                price: ds.price,
                marginBreach: ds.margin < this.MARGIN_FLOOR,
                capacityOver: ds.starDays > this.STAR_CAP,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtPrice(v) {
            // €000s → "€540,000" (en) / "€540.000" (es).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const full = Math.round(Number(v) * 1000);
            const grouped = full.toLocaleString(lang === `es` ? `de-DE` : `en-US`);
            return `€` + grouped;
        }

        _npsLabel(v) {
            if (v === null || v === undefined) return `—`;
            return (v > 0 ? `+` : ``) + Math.round(v);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const m = Number(v);
                const card = document.querySelector(`.cbesim-card-margin`);
                if (card) {
                    card.classList.toggle(`cbesim-margin-breach`, m < self.MARGIN_FLOOR);
                    card.classList.toggle(`cbesim-margin-warn`, m >= self.MARGIN_FLOOR && m < self.MARGIN_FLOOR + 4);
                    card.classList.toggle(`cbesim-margin-good`, m >= self.MARGIN_FLOOR + 4);
                }
                return `${Math.round(m)}%`;
            });

            uiManager.bind(`capacityDisplay`, `domainState.starDays`, (v) => {
                const s = Math.round(Number(v));
                const card = document.querySelector(`.cbesim-card-capacity`);
                if (card) {
                    card.classList.toggle(`cbesim-capacity-over`, s > self.STAR_CAP);
                    card.classList.toggle(`cbesim-capacity-tight`, s > self.STAR_CAP - 6 && s <= self.STAR_CAP);
                }
                return `${s} / ${self.STAR_CAP}`;
            });

            uiManager.bind(`npsDisplay`, `domainState.nps`, (v) => {
                const ds = window.mySimulation.state.domainState;
                if (!ds || !ds.npsSet) return `—`;
                return self._npsLabel(Number(v));
            });

            uiManager.bind(`repeatDisplay`, `domainState.repeat`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`priceDisplay`, `domainState.price`, (v) => {
                const p = Number(v);
                const bar = document.querySelector(`.cbesim-budget-bar`);
                if (bar) {
                    bar.classList.toggle(`cbesim-budget-over`, p > self.BUDGET + 60);
                    bar.classList.toggle(`cbesim-budget-under`, p < self.BUDGET - 60);
                }
                return self._fmtPrice(p);
            });

            // Diligence slider readout.
            const di = document.getElementById(`diligenceInput`);
            const diReadout = document.getElementById(`diligenceReadout`);
            if (di && diReadout) {
                diReadout.textContent = di.value;
                di.addEventListener(`input`, function() { diReadout.textContent = di.value; });
            }
        }

        getChartConfig() {
            return {
                cbeChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Program margin (%)`,
                                data: [],
                                borderColor: `#c9a44c`,
                                backgroundColor: `rgba(201,164,76,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#c9a44c`,
                                yAxisID: `y`
                            },
                            {
                                label: `Client NPS (÷2 + 50)`,
                                data: [],
                                borderColor: `#2f8f6f`,
                                backgroundColor: `rgba(47,143,111,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f8f6f`,
                                yAxisID: `y`
                            },
                            {
                                label: `Star-faculty utilisation (%)`,
                                data: [],
                                borderColor: `#2a4f87`,
                                backgroundColor: `rgba(42,79,135,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2a4f87`,
                                yAxisID: `y`
                            },
                            {
                                label: `Repeat-business rate (%)`,
                                data: [],
                                borderColor: `#7d5fc0`,
                                backgroundColor: `rgba(125,95,192,0.06)`,
                                borderWidth: 2,
                                borderDash: [2, 3],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 3,
                                pointBackgroundColor: `#7d5fc0`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#45506a`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#76819a` }, grid: { color: `rgba(20,36,63,0.06)` },
                                title: { display: true, text: `0–100 (indexed)`, color: `#76819a` }
                            },
                            x: {
                                ticks: { color: `#76819a` }, grid: { color: `rgba(20,36,63,0.04)` },
                                title: { display: true, text: `Round`, color: `#76819a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.marginHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // NPS (−100..+100) indexed onto the 0–100 axis: (nps/2)+50.
            const npsIndexed = ds.npsHistory.map((v) => Math.round((v / 2) + 50));
            // Star-faculty utilisation as % of the 40-day pool.
            const util = ds.starHistory.map((v) => Math.min(100, Math.round((v / this.STAR_CAP) * 100)));
            return {
                cbeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.marginHistory.map((v) => Math.round(v)) },
                        { data: npsIndexed },
                        { data: util },
                        { data: ds.repeatHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula incl. all gate caps.
            const margin = Math.round(ds.margin);
            const nps = Math.round(ds.nps);
            const starDays = Math.round(ds.starDays);
            const repeat = Math.round(ds.repeat);
            const util = Math.min(100, Math.round((starDays / this.STAR_CAP) * 100));
            const marginHeld = margin >= this.MARGIN_FLOOR;
            const capacityOk = starDays <= this.STAR_CAP;
            const npsStrong = nps >= 40;
            const marginScore = Math.max(0, Math.min(100, (margin - 15) * (100 / 30)));
            const npsScore = Math.max(0, Math.min(100, (nps + 100) / 2));
            const repeatScore = Math.max(0, Math.min(100, repeat));
            const utilScore = capacityOk ? Math.min(100, util + 20) : Math.max(0, 100 - (util - 100) * 4);
            let composite = Math.round(marginScore * 0.34 + npsScore * 0.30 + repeatScore * 0.22 + utilScore * 0.14);
            composite = Math.max(0, Math.min(100, composite));
            if (!marginHeld) composite = Math.min(composite, 45);
            if (!capacityOk) composite = Math.min(composite, 50);
            if (!npsStrong) composite = Math.min(composite, 62);
            if (ds.freeConcession) composite = Math.min(composite, 70);
            if (ds.droppedRepeat) composite = Math.min(composite, 72);
            return composite;
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="cp-cm-target ' + (ok ? 'cp-cm-met' : 'cp-cm-missed') + '">'
                    + '<span class="cp-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.marginHeld, t('tgt_margin'))
                + chip(!!summary.capacityOk, t('tgt_capacity'))
                + chip(!!summary.npsStrong, t('tgt_nps'))
                + chip(!!summary.repeatHeld, t('tgt_repeat'));
            const metric = function (label, val) {
                return '<div class="cp-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const npsStr = (typeof this._npsLabel === 'function') ? this._npsLabel(summary.nps != null ? summary.nps : null) : (summary.nps != null ? summary.nps : '-');
            const cap = (this.STAR_CAP != null) ? this.STAR_CAP : 40;
            const metrics = ''
                + metric(t('kpi_margin'), (summary.margin != null ? summary.margin : '-') + '%')
                + metric(t('kpi_nps'), npsStr)
                + metric(t('kpi_stardays'), (summary.starDays != null ? summary.starDays : '-') + '/' + cap)
                + metric(t('kpi_repeat'), (summary.repeat != null ? summary.repeat : '-') + '%');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="cp-cm">'
                +   '<div class="cp-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="cp-cm-verdict">' + verdict + '</div>'
                +   '<div class="cp-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="cp-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="cp-cm-targets">' + targets + '</div>'
                +   '<div class="cp-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="cp-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const margin = Math.round(ds.margin);
            const nps = Math.round(ds.nps);
            const starDays = Math.round(ds.starDays);
            const repeat = Math.round(ds.repeat);

            const util = Math.min(100, Math.round((starDays / this.STAR_CAP) * 100));
            const marginHeld = margin >= this.MARGIN_FLOOR;
            const capacityOk = starDays <= this.STAR_CAP;
            const npsStrong = nps >= 40;
            const repeatHeld = repeat >= this.START_REPEAT;

            // Composite balances the four KPIs on a 0–100 scale; each is normalised so no
            // single lever can saturate the score. Margin and capacity are hard gates.
            // Margin: 30% floor → 50, 45%+ → 100, 15% → 0.
            const marginScore = Math.max(0, Math.min(100, (margin - 15) * (100 / 30)));
            const npsScore = Math.max(0, Math.min(100, (nps + 100) / 2));   // −100..+100 → 0..100
            const repeatScore = Math.max(0, Math.min(100, repeat));
            const utilScore = capacityOk
                ? Math.min(100, util + 20)                                  // healthy utilisation rewarded
                : Math.max(0, 100 - (util - 100) * 4);                      // overshoot punished hard
            // v1.1.0 FIX A - composite (incl. all gate caps) delegated to _composite(ds) so the persisted
            // per-round score and this completion composite are identical by construction.
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.ordertaking && !marginHeld) pattern = `ordertaking`;
            else if (ds.overMargin && !npsStrong) pattern = `overmargin`;
            else if (!capacityOk || ds.capacityBlind) pattern = `capacity`;
            else if (marginHeld && npsStrong && capacityOk && repeatHeld) pattern = `solution`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (marginHeld && capacityOk && npsStrong && repeatHeld && composite >= 78) perfKey = `grade_solution`;
            else if (marginHeld && capacityOk && npsStrong) perfKey = `grade_profitable`;
            else if (ds.ordertaking && !marginHeld) perfKey = `grade_ordertaking`;
            else if (ds.overMargin && !npsStrong) perfKey = `grade_overmargin`;
            else if (!capacityOk) perfKey = `grade_capacity`;
            else if (composite >= 58) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (perfKey === `grade_solution`) insights.push(window.mySimulation.t(`insight_solution`));
            else if (pattern === `ordertaking`) insights.push(window.mySimulation.t(`insight_ordertaking`));
            else if (pattern === `overmargin`) insights.push(window.mySimulation.t(`insight_overmargin`));
            else if (pattern === `capacity`) insights.push(window.mySimulation.t(`insight_capacity`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!marginHeld) insights.push(window.mySimulation.t(`insight_margin_breach`));
            if (!capacityOk) insights.push(window.mySimulation.t(`insight_capacity_over`));
            if (ds.freeConcession) insights.push(window.mySimulation.t(`insight_free_concession`));
            if (ds.droppedRepeat) insights.push(window.mySimulation.t(`insight_dropped_repeat`));
            if (ds.soldActivity) insights.push(window.mySimulation.t(`insight_activity`));
            if (marginHeld && capacityOk && repeat < this.START_REPEAT) insights.push(window.mySimulation.t(`insight_repeat_slip`));

            return {
                gradeKey: perfKey,
                score: composite,
                margin: margin,
                nps: nps,
                starDays: starDays,
                repeat: repeat,
                utilisation: util,
                marginHeld: marginHeld,
                capacityOk: capacityOk,
                npsStrong: npsStrong,
                repeatHeld: repeatHeld,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.margin < this.MARGIN_FLOOR) return window.mySimulation.t(`hint_margin`);
            if (ds.starDays > this.STAR_CAP) return window.mySimulation.t(`hint_capacity`);
            if (ds.freeConcession) return window.mySimulation.t(`hint_concession`);
            if (ds.droppedRepeat && state.currentPeriod >= 3) return window.mySimulation.t(`hint_repeat`);
            if (ds.overMargin && ds.npsSet && ds.nps < 35) return window.mySimulation.t(`hint_premium`);
            if (ds.margin >= this.MARGIN_FLOOR && ds.starDays <= this.STAR_CAP && ds.npsSet && ds.nps >= 40) return window.mySimulation.t(`hint_strong`);
            return null;
        }

